// Define a capability
public static final Capability<IInventory> INVENTORY_CAPABILITY = CapabilityManager.get(
    new CapabilityToken<>() {}
);

// Attach to an entity
@SubscribeEvent
public static void registerCapabilities(RegisterCapabilitiesEvent event) {
    event.registerBlockEntity(BlockEntity.class, INVENTORY_CAPABILITY, BlockEntity::getInventory);
}

// Use capability
player.getCapability(INVENTORY_CAPABILITY).ifPresent(inv -> {
    // Use inventory
});
